export const SENSE_KEYS = Object.keys(SENSES);

/** Every field any sense sets, at any rank. The runtime has to read all of
 *  them; test_round114_perception asserts exactly that. */
export const SENSE_FIELDS = ["bloodSense","bondSense","counterSense","dangerSense","deathWatch","echoSense","flawSight","healthbars","heatSight","leySight","lurkReveal","mapMemory","mapSense","nightVision","noFlank","nodeSense","perception","pickupRadiusMult","rootSense","scentTrail","siteSense","tremorSense","unmask","weakspotCrit"];

/** The user's own split, carried through from the CSV: what the runtime
 *  already read when they wrote the file, and what it had to grow. Kept
 *  because it is the build list, and a check can hold the two apart. */
export const SENSE_FIELDS_LIVE = ["bondSense","healthbars","lurkReveal","mapSense","nightVision","perception","pickupRadiusMult","weakspotCrit"];
export const SENSE_FIELDS_PENDING = ["bloodSense","counterSense","dangerSense","deathWatch","echoSense","flawSight","heatSight","leySight","mapMemory","noFlank","nodeSense","rootSense","scentTrail","siteSense","tremorSense","unmask"];

/** What each pending field is for, in the user's words. */
export const PENDING_NOTES = {"bloodSense":{"note":"outline and rank enemies by missing health","usedBy":["healthbars","scentTrail","bloodInTheWater","deathwatch"]},"counterSense":{"note":"outline whatever is currently perceiving YOU","usedBy":["counterSense"]},"dangerSense":{"note":"directional flash when something off-screen acquires you","usedBy":["bondsense","tremorSense","dangerSense","compoundEyes","stillness","herdSense","staticSense"]},"deathWatch":{"note":"show exact remaining health as a number","usedBy":["healthbars","bloodInTheWater","deathwatch"]},"echoSense":{"note":"radius; reveal MOVING bodies through terrain","usedBy":["echolocation","stillness"]},"flawSight":{"note":"name a target's lowest resistance on its bar","usedBy":["weakspots","leySight","rangefinder","staticSense"]},"heatSight":{"note":"radius; living bodies through cover, NOT undead or constructs","usedBy":["heatSight"]},"leySight":{"note":"mark casters, enchanted objects and warded ground","usedBy":["unmask","leySight","staticSense"]},"mapMemory":{"note":"explored minimap persists between visits","usedBy":["mapsense","gathering","leySight","rootNetwork"]},"noFlank":{"note":"no rear arc: cannot be flanked or backstabbed","usedBy":["dangerSense","compoundEyes","herdSense"]},"nodeSense":{"note":"harvest nodes on the minimap","usedBy":["mapsense","gathering","rootNetwork"]},"rootSense":{"note":"radius; anything touching vegetation","usedBy":["rootNetwork"]},"scentTrail":{"note":"seconds of trail to draw behind creatures","usedBy":["scentTrail"]},"siteSense":{"note":"ping sites whose `held` is not null","usedBy":["mapsense","gathering","leySight"]},"tremorSense":{"note":"radius; ground-contact bodies only, ignores fliers","usedBy":["tremorSense"]},"unmask":{"note":"radius; strip illusion, disguise and stealth","usedBy":["truesight","unmask","counterSense"]}};

/** The sense's state at a rank, and everything at or below it. 'mods' is
 *  already the full state, so this is a lookup rather than a fold -- but it
 *  clamps, because a slot can sit at a rank the table has no row for. */
export function senseAt(key, rank) {
  const s = SENSES[key];
  if (!s) return null;
  const i = Math.max(0, SENSE_RANKS.indexOf(rank));
  return s.ranks[SENSE_RANKS[i]] || s.ranks.normal;
}

/** Which senses a socket can surface. Essence id first because it is the most
 *  specific statement, then the essence's family, then the stone's -- the same
 *  order every other selector in this project uses. Returns [] rather than a
 *  fallback: the caller decides what "no opinion" means. */
export function sensesFor({ essenceId = null, family = null, stoneFamily = null } = {}) {
  const out = [];
  for (const s of Object.values(SENSES)) {
    if (essenceId && s.essences.includes(essenceId)) { out.push(s); continue; }
    if (family && s.families.includes(family)) { out.push(s); continue; }
    if (stoneFamily && s.stones.includes(stoneFamily)) out.push(s);
  }
  return out;
}

